// r0-sheet-attribution — heuristic segmentation of the main www CSS sheet.
// Method (documented in r0-census.md §e): brace-match the whole file into
// regions; the five TW4 `@layer <name>{` blocks are matched by name; all
// bytes outside any layer = "unlayered". Inside @layer components AND the
// unlayered zone, split top-level rules (brace depth 0→1) and classify each
// rule by FIRST-MATCH marker priority: jx-pure > jixoai > svelte-scoped >
// site-module > residual. theme/base/utilities/properties layers are
// attributed whole (TW4-generated by construction). Known error sources:
// marker priority collisions, TW4 merging imported sheets into layers
// (boundary blur), component styles that both define --jx-* and reference
// var(--jx-*) (definition-pattern `--jx-…:` wins the jixoai bucket).
const fs = require("fs");
const file = process.argv[2];
const s = fs.readFileSync(file, "utf8");
const bytes = (str) => Buffer.byteLength(str, "utf8");

// string-aware brace matcher: skips "..." '...' contents (escaped quotes
// honored) so braces inside content:"{...}" or data: URIs cannot break depth
function matchBrace(open) {
  let depth = 1, i = open + 1, quote = null;
  while (depth > 0 && i < s.length) {
    const c = s[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
    } else if (c === '"' || c === "'") quote = c;
    else if (c === "{") depth++;
    else if (c === "}") depth--;
    i++;
  }
  return i; // index AFTER closing brace
}

// brace-match regions of `@layer NAME{` at top level
const layers = [];
{
  const re = /@layer ([a-z]+)\{/g;
  let m;
  while ((m = re.exec(s))) {
    const end = matchBrace(m.index + m[0].length - 1);
    layers.push({ name: m[1], start: m.index, end }); // end = index AFTER closing brace
    re.lastIndex = end;
  }
}
// unlayered segments = gaps between/before/after layers
const unlayered = [];
{
  let pos = 0;
  for (const L of layers) {
    if (L.start > pos) unlayered.push([pos, L.start]);
    pos = L.end;
  }
  if (pos < s.length) unlayered.push([pos, s.length]);
}

// top-level rule splitter for a [start,end) char region (string-aware).
// A rule span runs from the character AFTER the previous rule's closing
// brace (so the selector/prelude is included) through its own closing brace.
function rulesOf(start, end) {
  const out = [];
  let i = start, quote = null, ruleStart = start;
  while (i < end) {
    const c = s[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
      i++;
      continue;
    }
    if (c === '"' || c === "'") { quote = c; i++; continue; }
    if (c === "{") {
      const j = matchBrace(i);
      out.push([ruleStart, Math.min(j, end)]);
      i = j;
      ruleStart = j;
      continue;
    }
    i++;
  }
  return out;
}

const B = {};
const add = (bucket, text, countRules = 1) => {
  B[bucket] ??= { bytes: 0, rules: 0 };
  B[bucket].bytes += bytes(text);
  B[bucket].rules += countRules;
};

// marker buckets (first-match priority order)
const machineryAt = /^@(property|keyframes|font-face|charset|import)\b/;
const jxPure = /:where\(\.jx-pure|\.jx-html-[a-z-]+|\.jx-control-lane|\.jx-control-shell|\.jx-control\b|\.jx-slider|\.jx-switch-(sm|lg)|\.jx-tgroup|\.jx-error-mark|\.jx-error\b|\.jx-field|\.jx-label\b|\.jx-color-(shell|swath|swatch|expand|picker-chevron)/;
const jixoai = /--brand-hue|\.jx-hue-|\[data-density|\.jx-light|\.jx-surface|\.jx-press|--jx-[a-z0-9-]+\s*:|\.jx-dark|\.jx-reveal/;
const svelteScoped = /svelte-[0-9a-z]{6}/;
const siteModule = /\.data-table|\.table-scroll|--tok-|\.token-lab/;
const residualPrefixes = new Map();

function classify(ruleText) {
  const prelude = ruleText.slice(0, ruleText.indexOf("{")).trim();
  if (machineryAt.test(prelude)) return "TW4+entry machinery (@property/@keyframes/@font-face)";
  if (jxPure.test(ruleText)) return "jx-pure.css zone (css-laws faces + Tier-2)";
  if (jixoai.test(ruleText)) return "jixoai.css zone (token sheet)";
  if (svelteScoped.test(ruleText)) return "component <style> (svelte-scoped)";
  if (siteModule.test(ruleText)) return "site modules";
  if (/^@(supports|media|container)/.test(prelude)) return "TW4+entry machinery (@property/@keyframes/@font-face)"; // wrapper w/o recognizable inner marker
  const pfx = (prelude.match(/^\.?[a-zA-Z][a-zA-Z0-9_-]*/) || ["?"])[0];
  residualPrefixes.set(pfx, (residualPrefixes.get(pfx) || 0) + 1);
  return "residual (unattributed)";
}

for (const L of layers) {
  const whole = s.slice(L.start, L.end);
  const open = s.indexOf("{", L.start); // the layer's own opening brace
  const innerRules = rulesOf(open + 1, L.end - 1); // rules INSIDE the layer body
  if (L.name === "components") {
    for (const [a, b] of innerRules) add(classify(s.slice(a, b)), s.slice(a, b));
  } else {
    // theme/base/utilities/properties attributed whole (TW4-generated)
    const label = { theme: "TW4 theme tokens layer", base: "TW4 preflight (base layer)", utilities: "TW utilities layer", properties: "TW4 property/var machinery layer" }[L.name];
    add(label, whole, innerRules.length);
  }
}
for (const [a, b] of unlayered) {
  for (const [x, y] of rulesOf(a, b)) add("UNLAYERED: " + classify(s.slice(x, y)), s.slice(x, y));
}

const totalBytes = bytes(s);
console.log(`file: ${file}`);
console.log(`total_bytes: ${totalBytes} (utf8 string len ${s.length})`);
const layersSum = layers.reduce((t, L) => t + bytes(s.slice(L.start, L.end)), 0);
console.log(`layer_spans: ` + layers.map((L) => `${L.name}[${L.start}:${L.end}]`).join(" "));
console.log(`unlayered_segments: ${unlayered.map(([a, b]) => `[${a}:${b}](${b - a}ch)`).join(" ") || "none"}`);
let acc = 0;
for (const [k, v] of Object.entries(B).sort((x, y) => y[1].bytes - x[1].bytes)) {
  const pct = ((v.bytes / totalBytes) * 100).toFixed(1);
  acc += v.bytes;
  console.log(`${String(v.bytes).padStart(7)}B ${String(pct).padStart(5)}%  rules=${String(v.rules).padStart(5)}  ${k}`);
}
console.log(`accounted: ${acc}B / ${totalBytes}B (diff ${totalBytes - acc}B = inter-rule whitespace at unlayered gaps)`);
console.log(`residual_selector_prefix_histogram: ${[...residualPrefixes.entries()].sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}=${v}`).join(" ")}`);
